import { every } from "../fivem/scheduler";
import { cellKey, createLogger, isRecord } from "../shared";
import { readFinite } from "../shared/strict";
import { cache } from "./cache";

/**
 * The model point scan: for each point, the nearest world object (or vehicle) of its models within its radius, two
 * times a second, told only when it changes. ai-lib runs one for every resource's prompt-mode model points
 * (`modelHost.ts`); a resource runs its own only while ai-lib does not.
 */

const log = createLogger(GetCurrentResourceName());

/** What the scan needs of a model point (its label, `canShow` and action stay with the owner). */
export interface ModelScanDef {
  /** Model hashes; none with `vehicles` = every networked vehicle. */
  models: number[];
  /** The models are vehicles: the vehicle pool is walked instead of objects. */
  vehicles: boolean;
  radius: number;
  /** Object points are skipped while the player sits in a vehicle unless this is true. */
  inVehicle: boolean;
}

/** A definition from another resource (ai-lib's export); null when malformed. */
export function readModelScanDef(value: unknown): ModelScanDef | null {
  if (!isRecord(value) || !Array.isArray(value.models)) return null;
  const models = value.models.filter((m): m is number => Number.isInteger(m));
  const radius = readFinite(value.radius);
  if (radius === null || radius <= 0 || radius > CELL - MOVE_MARGIN)
    return null;
  return {
    models,
    vehicles: value.vehicles === true,
    radius,
    inVehicle: value.inVehicle === true,
  };
}

const SCAN_MS = 500;
/** Up to this many models a point asks GTA for the closest object of each; more models use the object index. */
const DIRECT_MODELS = 6;
/** Pool entries the object index reads per scan, so a big pool is spread over several scans. */
const INDEX_CHUNK = 300;
/** Indexed objects are filtered by where they stood when found; this margin covers ones moved since. */
const MOVE_MARGIN = 2;
/** Grid cell of the object index, in metres: at least the largest radius plus the margin, so 3 x 3 cells cover it. */
const CELL = 64;
/** While the player stands still (and stays in or out of a vehicle) a scan is skipped, but not more than this many in a row. */
const IDLE_SCANS = 6;

/**
 * The objects whose model a many-model point wants (364 chair models, say): one closest-object query per model and
 * scan costs milliseconds, so the object pool is walked instead, a chunk per scan, and only matching objects are kept
 * with the place they stood.
 */
class ObjectIndex {
  /** Matching objects found by the last complete walk, by grid cell: entity, then x, y, z. */
  cells = new Map<number, number[]>();
  private pool: number[] = [];
  private next = 0;
  private found = new Map<number, number[]>();

  advance(wanted: Set<number>): void {
    if (this.next >= this.pool.length) {
      this.cells = this.found;
      this.found = new Map();
      this.pool = GetGamePool("CObject") as number[];
      this.next = 0;
    }
    const end = Math.min(this.pool.length, this.next + INDEX_CHUNK);
    for (let i = this.next; i < end; i++) {
      const entity = this.pool[i] ?? 0;
      if (!entity || !wanted.has(GetEntityModel(entity))) continue;
      const [x = 0, y = 0, z = 0] = GetEntityCoords(entity, false);
      const key = cellKey(Math.floor(x / CELL), Math.floor(y / CELL));
      const cell = this.found.get(key);
      if (cell) cell.push(entity, x, y, z);
      else this.found.set(key, [entity, x, y, z]);
    }
    this.next = end;
  }
}

class Scan {
  readonly hashSet: Set<number>;
  /** Every networked vehicle, whatever its model (`Points.addVehicle`). */
  readonly global: boolean;
  readonly indexed: boolean;

  constructor(
    readonly def: ModelScanDef,
    readonly onNearest: (entity: number) => void,
    public entity: number,
  ) {
    this.hashSet = new Set(def.models);
    this.global = def.vehicles && def.models.length === 0;
    this.indexed = !def.vehicles && def.models.length > DIRECT_MODELS;
  }

  /** Object points rest while the player sits in a vehicle (unless `inVehicle`). */
  skipped(inVehicle: boolean): boolean {
    return inVehicle && !this.def.vehicles && !this.def.inVehicle;
  }
}

/** Something near the player this scan: entity, model, distance. */
interface Near {
  entity: number;
  model: number;
  dist: number;
}

/**
 * A set of model points scanned by one scheduler job (500 ms, only while it holds points). Scans are skipped while
 * the player stands still, refreshed every 3 s; the vehicle pool is walked once per scan for every vehicle point and
 * the object index once for every many-model point.
 */
export class ModelScanner {
  private readonly scans = new Map<string, Scan>();
  private readonly index = new ObjectIndex();
  /** Models of every many-model point, rebuilt when the points change. */
  private wanted: Set<number> | null = null;
  private readonly last = {
    x: 0,
    y: 0,
    z: 0,
    inVehicle: false,
    idle: IDLE_SCANS,
  };
  private readonly job = every(SCAN_MS, () => this.scan(), {
    active: false,
    name: "modelPoints",
  });

  /** Adds (or replaces) a point; `entity` seeds the nearest one already known (a hand-over), so only a change is told. */
  add(
    key: string,
    def: ModelScanDef,
    onNearest: (entity: number) => void,
    entity = 0,
  ): void {
    this.scans.set(key, new Scan(def, onNearest, entity));
    this.wanted = null;
    // The next scan runs even if the player stands still.
    this.last.idle = IDLE_SCANS;
    this.job.set(true);
  }

  remove(key: string): void {
    if (!this.scans.delete(key)) return;
    this.wanted = null;
    this.job.set(this.scans.size > 0);
  }

  get size(): number {
    return this.scans.size;
  }

  private scan(): void {
    const [x = 0, y = 0, z = 0] = GetEntityCoords(cache.ped, false);
    const inVehicle = cache.vehicle !== false;
    const last = this.last;
    const still =
      inVehicle === last.inVehicle &&
      Math.hypot(x - last.x, y - last.y, z - last.z) < 1;
    if (still && ++last.idle < IDLE_SCANS) return;
    Object.assign(last, { x, y, z, inVehicle, idle: 0 });

    let vehicleRadius = 0;
    let indexRadius = 0;
    for (const scan of this.scans.values()) {
      if (scan.skipped(inVehicle)) continue;
      if (scan.def.vehicles)
        vehicleRadius = Math.max(vehicleRadius, scan.def.radius);
      else if (scan.indexed)
        indexRadius = Math.max(indexRadius, scan.def.radius);
    }
    const vehicles = vehicleRadius
      ? this.nearVehicles(x, y, z, vehicleRadius)
      : [];
    const objects = indexRadius ? this.nearIndexed(x, y, z, indexRadius) : [];

    for (const scan of this.scans.values()) {
      const found = scan.skipped(inVehicle)
        ? 0
        : scan.def.vehicles
          ? nearestOf(vehicles, scan)
          : scan.indexed
            ? nearestOf(objects, scan)
            : closestObject(x, y, z, scan);
      if (found === scan.entity) continue;
      scan.entity = found;
      try {
        scan.onNearest(found);
      } catch (error) {
        log.error("model point handler failed", error);
      }
    }
  }

  /** Vehicles within `radius`: one pool walk for every vehicle point. */
  private nearVehicles(x: number, y: number, z: number, radius: number) {
    const near: Near[] = [];
    for (const entity of GetGamePool("CVehicle") as number[]) {
      const [vx = 0, vy = 0, vz = 0] = GetEntityCoords(entity, false);
      const dist = Math.hypot(vx - x, vy - y, vz - z);
      if (dist < radius)
        near.push({ entity, model: GetEntityModel(entity), dist });
    }
    return near;
  }

  /** Indexed objects within `radius`: filtered by where they stood when found, then checked where they are now. */
  private nearIndexed(x: number, y: number, z: number, radius: number) {
    if (!this.wanted) {
      this.wanted = new Set();
      for (const scan of this.scans.values())
        if (scan.indexed)
          for (const hash of scan.def.models) this.wanted.add(hash);
    }
    this.index.advance(this.wanted);
    const near: Near[] = [];
    const reach = (radius + MOVE_MARGIN) ** 2;
    const cx = Math.floor(x / CELL);
    const cy = Math.floor(y / CELL);
    for (let ox = -1; ox <= 1; ox++)
      for (let oy = -1; oy <= 1; oy++) {
        const list = this.index.cells.get(cellKey(cx + ox, cy + oy));
        if (list) this.nearIn(list, x, y, z, radius, reach, near);
      }
    return near;
  }

  /** The objects of one index cell within `radius` (filtered by `reach` on their found place first). */
  private nearIn(
    list: number[],
    x: number,
    y: number,
    z: number,
    radius: number,
    reach: number,
    near: Near[],
  ): void {
    for (let i = 0; i < list.length; i += 4) {
      const dx = (list[i + 1] ?? 0) - x;
      const dy = (list[i + 2] ?? 0) - y;
      const dz = (list[i + 3] ?? 0) - z;
      if (dx * dx + dy * dy + dz * dz > reach) continue;
      const entity = list[i] ?? 0;
      if (!DoesEntityExist(entity)) continue;
      const [ox = 0, oy = 0, oz = 0] = GetEntityCoords(entity, false);
      const dist = Math.hypot(ox - x, oy - y, oz - z);
      if (dist < radius)
        near.push({ entity, model: GetEntityModel(entity), dist });
    }
  }
}

/** The nearest of `near` that this point takes (its models, or any networked vehicle for a global one) within its radius. */
function nearestOf(near: Near[], scan: Scan): number {
  let found = 0;
  let best = scan.def.radius;
  for (const item of near) {
    if (item.dist >= best) continue;
    if (
      scan.global
        ? !NetworkGetEntityIsNetworked(item.entity)
        : !scan.hashSet.has(item.model)
    )
      continue;
    found = item.entity;
    best = item.dist;
  }
  return found;
}

/** A point with few models asks GTA for the closest object of each. */
function closestObject(x: number, y: number, z: number, scan: Scan): number {
  for (const hash of scan.def.models) {
    const found = GetClosestObjectOfType(
      x,
      y,
      z,
      scan.def.radius,
      hash,
      false,
      false,
      false,
    );
    if (found) return found;
  }
  return 0;
}
